def shuffle(L):
    for qi,q in enumerate(L['quiz']):
        sh=[1,2,0,2,1,0,1,0,2,1,2,0][qi%12];o=q['o'];c=o[q['a']];o=o[sh:]+o[:sh] if sh else o;q['o']=o;q['a']=o.index(c)
    return L
